   Exemple avec Yaf_View_Simple::display


<?php
class IndexController extends Yaf_Controller_Abstract
{
    public function indexAction()
    {
        $this->getView()->assign("title", "Ma page d'accueil");

        /* effectue le rendu de index/index.phtml et stocke le résultat
         * dans le corps de la réponse */
        $this->getView()->display("index/index.phtml");

        return false; // le rendu a été fait ici, on ignore le rendu automatique
    }
}
?>




